#include <iostream>
#include <map>
#include <sstream>
#include <string>
#include <unordered_set>

int main() {
    std::map<std::string, int> counts;
    std::istringstream text("to be or not to be");
    for (std::string w; text >> w;) ++counts[w];       // intentional insert-or-update.

    for (const auto& [word, n] : counts)               // sorted: be, not, or, to.
        std::cout << word << ' ' << n << '\n';

    if (auto it = counts.find("zebra"); it != counts.end())   // lookup only.
        std::cout << it->second << '\n';
    std::cout << counts.size() << '\n';                // still 4: no phantom entry.

    std::unordered_set<std::string> seen{"to", "be"};
    bool known = seen.contains("or");                  // C++20: false.
    (void)known;
}
```

| Need | Container | Lookup |
|---|---|---|
| key to value, sorted output. | `std::map`. | O(log n). |
| key to value, fastest lookup. | `std::unordered_map`. | O(1) average. |
| membership only. | `std::set` / `std::unordered_set`. | same as above. |

